// CSD_RATIONALE_BEGIN
// Root-cause of accuracy regression: Phase 3 fires AFTER Phase 1 and generates
// cold constrained expressions (no prior reasoning context), producing wrong
// answers 100% of the time (0/11 with activity correct). Attempt 34's 49%
// accuracy came from the model writing correct free-form <<int(expr)>> spans
// naturally. The 4 syntax failures (malformed_constrained_content) come from
// the model using {var} template syntax inside spans, which the parser rejects.
//
// Fix: CRANE-style hybrid decoding:
//   Phase 1: Unconstrained outside spans; detect << via RenderedEndsWith;
//     when << detected, immediately enter constrained mode (no extra <<).
//   Phase 2: CloseSpanWithinBudget(spanBudget) — generates constrained content
//     with the FULL reasoning context already in `generated`, so the LM sees
//     all its step-by-step work before the open delimiter and writes the same
//     expression it would have written freely, but now under parser control
//     (parser rejects { and ** so all syntax failures are prevented).
//   After close: exit span, continue unconstrained (may write more reasoning
//     and further spans; evaluator extracts the last complete one).
//   Phase 3 (conservative): only triggers if closeCount == 0 after budget;
//     opens a fresh constrained span as final fallback.
//
// Expected: constrained generation HOT (with full context) should maintain
// ~38–49% accuracy while fixing 4–6 syntax failures → syntax ≥90%.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// 1. parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//    Outside-span branch: insideConstrainedOut is only flipped true after
//    RenderedEndsWith(generated, "<<") is true and we set currentConstrainedOut := [].
//    parser.IsValidPrefix([]) holds by the method's requires clause, so the
//    invariant is immediately established. While outside, the invariant is
//    vacuously true (antecedent false).
//
//    Inside-span branch (CloseSpanWithinBudget): the helper's postcondition
//    directly guarantees insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//    for the returned (ci, cc) pair, covering both the close path (antecedent
//    false → vacuously true) and the still-open path (consequent provided).
//
//    Phase 3: OpenConstrainedSpan sets insideConstrainedOut := true and
//    currentConstrainedOut := []; parser.IsValidPrefix([]) holds by requires.
//    Subsequent CloseSpanWithinBudget postcondition restores validity. ✓
//
// 2. progress: |generated| <= |generatedPrefix| + steps
//
//    Outside-span branch: steps incremented by 1 before any append. EOS path
//    leaves generated unchanged so |generated| < |generatedPrefix| + steps.
//    Normal append grows generated by exactly 1 and steps by 1, preserving
//    |generated| = |generatedPrefix| + steps_new. Detecting << and entering
//    constrained mode does not modify generated or steps. ✓
//
//    Inside-span branch: CloseSpanWithinBudget postcondition gives
//    |cg| <= |generated_old| + budget. We then set steps := steps_old + budget.
//    So |generated_new| <= |generatedPrefix| + steps_old + budget = |generatedPrefix|
//    + steps_new. EOS and dead-end tokens consumed inside the helper count
//    toward `budget` but produce no visible output, so visible length growth
//    is at most budget. Budget satisfies budget <= maxSteps - steps_old, ensuring
//    steps_new <= maxSteps. ✓
//
//    Termination: inside branch increases steps by budget >= 1 each iteration
//    (remaining >= 1 since steps < maxSteps). Outside branch increases by 1.
//    Both ensure maxSteps - steps strictly decreases. ✓
// CSD_PROOF_SKETCH_END

  generated := generatedPrefix;
  insideConstrainedOut := insideConstrained;
  currentConstrainedOut := currentConstrained;
  cost := 0;

  helpers.AppendTaskGuidance(lm,
    "Solve this math problem step by step. " +
    "After reasoning, write the final answer inside << >> as <<int(expr)>> " +
    "using plain variable names (NO curly braces: write n not {n}, write price not {price}). " +
    "Allowed operators: +, -, *, /, //, (, ), int(). " +
    "Example: <<int(n * price - discount)>>");

  var spanBudget: nat := 40;
  var steps: nat := 0;

  if insideConstrainedOut {
    // Entry with an already-open constrained span: close it within budget.
    if steps < maxSteps {
      var remaining0: nat := maxSteps - steps;
      var budget0: nat := if remaining0 <= spanBudget then remaining0 else spanBudget;
      var cg0, ci0, cc0 := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget0
      );
      generated := cg0;
      insideConstrainedOut := ci0;
      currentConstrainedOut := cc0;
      steps := steps + budget0;
    }
  } else {
    // Main CRANE-style loop: unconstrained outside spans, constrained inside.
    while steps < maxSteps
      invariant 0 <= steps <= maxSteps
      invariant lm.ValidTokensIdsLogits()
      invariant !insideConstrainedOut ==> currentConstrainedOut == []
      invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
      invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
      invariant |generated| <= |generatedPrefix| + steps
      decreases maxSteps - steps
    {
      if !insideConstrainedOut {
        var next := helpers.UnconstrainedStep(lm, prompt, generated);
        steps := steps + 1;
        if next == eosToken {
          break;
        }
        generated := generated + [next];
        if RenderedEndsWith(generated, "<<") {
          // Model opened a constrained span: switch to constrained mode.
          // Do NOT append another <<; the one already in generated is the open delimiter.
          insideConstrainedOut := true;
          currentConstrainedOut := [];
        }
      } else {
        // Inside a constrained span: close it with parser-controlled generation.
        // The full reasoning context is in `generated` (including the open <<),
        // so CloseSpanWithinBudget generates the expression with maximum context.
        var remaining: nat := maxSteps - steps;
        var budget: nat := if remaining <= spanBudget then remaining else spanBudget;
        var cg, ci, cc := helpers.CloseSpanWithinBudget(
          lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget
        );
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + budget;
      }
    }

    // Phase 3 (conservative fallback): only if no complete span was written at all.
    if !insideConstrainedOut && steps < maxSteps {
      var generatedStr := CSDHelpers.PrefixToString(generated);
      var closeCount := CSDHelpers.CountSubstring(generatedStr, ">>");
      if closeCount == 0 {
        // No complete span at all — open a fresh constrained span as final answer.
        var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
        generated := og;
        insideConstrainedOut := oi;
        currentConstrainedOut := oc;
        steps := steps + 1;
        if insideConstrainedOut && steps < maxSteps {
          var remaining3: nat := maxSteps - steps;
          var budget3: nat := if remaining3 <= spanBudget then remaining3 else spanBudget;
          var cg3, ci3, cc3 := helpers.CloseSpanWithinBudget(
            lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget3
          );
          generated := cg3;
          insideConstrainedOut := ci3;
          currentConstrainedOut := cc3;
          steps := steps + budget3;
        }
      }
    }
  }

  cost := steps;

